body.usercss:

div.normalButton {
    display: block;
    z-index: 1;
    float: right;
    padding: 10px;
}

body.onloadscript:

callFunction("parent", "changeHeaderIcon", ["b", "show", "new,save"]);

Sepoa.attachEvent("onButtonClick", function(id) {
    switch (id) {
        case "new":
            doNewWrite();
            break;

        case "save":
            doSave();
            break;

        case "restoreButton":
            doRestore();
            break;

        case "deleteButton":
            doDelete();
            break;
    }
});

userscript.function:

if (!formObj.validate()) {

    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

if (!doCheckPassword(formObj.getValue("PASSWORD"), formObj.getValue("PASSWORD_CONFIRM"))) {
    Alert(Sepoa.cache.text.get('AD_025.0003'));
    return;
}

Confirm(Sepoa.cache.text.get('AD_025.0001'), function(result) {
    if (result) {
        if (g_new_ref.editForm == true) {
            doUpdate();
        } else {
            doInsert();
        }
    }
});


var house_code = formObj.getValue("HOUSE_CODE");
var user_id = formObj.getValue("USER_ID");
var is_exist = false;

doServiceAjax('sepoa.svc.admin.AD_025', 'CONNECTION', 'doUserCheck', {
    USER_ID: user_id,
    HOUSE_CODE: house_code
}, function(so) {

    if (so.status != 1) {
        Alert(so.message);
        return;
    }

    var sf = new SepoaFormater(so.result[0]);

    if (sf.getValue("IS_EXIST") === "true") {
        is_exist = true;
    }

}, false);

if (is_exist) {
    Alert(Sepoa.cache.text.get('AD_025.0005'));
    return;
}

doServiceAjax('sepoa.svc.admin.AD_025', 'TRANSACTION', 'doInsertForm', null, function(so) {

    if (so.status != 1) {
        Alert(so.message);
        return;
    }

    Alert(Sepoa.cache.text.get('MESSAGE.0001'));

    callFunction('AD_025_1', 'doQueryList', []);
});


var house_code = formObj.getValue("HOUSE_CODE");
var user_id = formObj.getValue("USER_ID");

doServiceAjax('sepoa.svc.admin.AD_025', 'TRANSACTION', 'doUpdateForm', null, function(so) {

    if (so.status != 1) {
        Alert(so.message);
        return;
    }

    Alert(Sepoa.cache.text.get('MESSAGE.0001'));

    doQueryForm(house_code, user_id);
});


var house_code = formObj.getValue("HOUSE_CODE");
var user_id = formObj.getValue("USER_ID");

Confirm(Sepoa.cache.text.get('AD_025.0002'), function(result) {
    if (result) {
        doServiceAjax('sepoa.svc.admin.AD_025', 'TRANSACTION', 'doRestore', {
            HOUSE_CODE: house_code,
            USER_ID: user_id
        }, function(so) {
            if (so.status != 1) {
                Alert(so.message);
                return;
            }

            Alert(Sepoa.cache.text.get('MESSAGE.0001'));

            doQueryForm(house_code, user_id);

        });
    }
});


var house_code = formObj.getValue("HOUSE_CODE");
var user_id = formObj.getValue("USER_ID");

Confirm(Sepoa.cache.text.get('AD_025.0006'), function(result) {
    if (result) {
        doServiceAjax('sepoa.svc.admin.AD_025', 'TRANSACTION', 'doDelete', {
            HOUSE_CODE: house_code,
            USER_ID: user_id
        }, function(so) {
            if (so.status != 1) {
                Alert(so.message);
                return;
            }

            Alert(Sepoa.cache.text.get('MESSAGE.0001'));

            callFunction('AD_025_1', 'doQueryList', []);
        });
    }
});


formObj.clear();
g_new_ref.editForm = false;

formObj.setValue("COUNTRY", "KR");
formObj.setValue("DATE_FORMAT", "%Y/%m/%d");
formObj.setValue("HOUSE_CODE", "000");
formObj.setReadonly("USER_ID", false);
formObj.setReadonly("EMAIL", false);
formObj.setReadonly("PASSWORD", true);
formObj.setReadonly("PASSWORD_CONFIRM", true);

doDisableForm('false');

callFunction('AD_025_1', 'doRowUnSelect', []);


doServiceAjax('sepoa.svc.admin.AD_025', 'CONNECTION', 'doQueryForm', {
    HOUSE_CODE: house_code,
    USER_ID: user_id
}, function(so) {
    if (so.status != 1) {
        Alert(so.message);
        return;
    }

    var sf = new SepoaFormater(so.result[0]);

    if (sf.getRowCount() > 0) {
        formObj.dataMapper(sf);

        g_new_ref.editForm = true;

        formObj.setReadonly("USER_ID", true);
        formObj.setReadonly("EMAIL", true);
        formObj.setReadonly("PASSWORD", false);
        formObj.setReadonly("PASSWORD_CONFIRM", false);
    }
}, false);


var headerSwitch = flag === "true" ? "hide" : "show";

callFunction('parent', 'changeHeaderIcon', ['b', headerSwitch, 'new,save']);

formObj.setViewMode(flag === "true");
btnObj.showButton('restoreButton', flag === "true");
btnObj.showButton('deleteButton', flag === "true");


if (password != password_confirm) {
    return false;
}

return true;


switch (itemName) {

    case "USER_ID":

        formObj.setValue("EMAIL", itemValue + "@sepoasoft.co.kr");
        break;
    case "EMAIL":

        var index = itemValue.indexOf("@");

        if (index > 0) {
            formObj.setValue("USER_ID", itemValue.substring(0, index));
        }

        break;
}

return true;
